        "summary": "王马社区成立于2001年，地处杭州市中心，占地面积0.34平方公里，住户5934户，常住人口近1.6万，是典型的城市社区。社区党委下辖26个党支部，在册党员704人。先后获得全国文明单位、全国和谐社区建设示范社区、全国百佳学习型社区、浙江省先进基层党组织、浙江省城市社区党建工作示范社区、浙江省和谐示范社区等荣誉称号。\n多年来，王马社区始终坚持以党建为引领，靠党建凝聚党员、服务群众、促进和谐，着力打造“红色王马、幸福家园”。把党支部建在家门口，这里，曾是全国第一个楼道党支部的诞生地；把服务送到家门口，这里，有杭州人倍感自豪的“66810”为民服务法；把议事桌摆在家门口，这里，社区治理创新得到了生动实践。"
