        "summary": "杭州市上城区凯旋街道南肖埠社区以其卓越的基层群众性自治实践，荣获“全国先进基层群众性自治组织”称号。该社区居民委员会秉持“专业、敬业、爱业，善学、善新、善治”的理念，致力于打造“家庭式、亲情型、数字化”的现代智能化社区。社区通过创立“姐妹帮扶团”等自治帮扶型社会组织，积极培育孵化社区自治力量，形成了包括“绿邻聚落部”在内的26家社会组织，并整合为枢纽型社会组织“南肖埠陆号”。同时，社区打造了街道级为老服务品牌“凯乐耆”，坚持志愿招募机制，推行爱心积分兑换，有效激发了志愿服务组织的活力。\n南肖埠社区还注重居民自治与网格化服务管理的有效衔接，通过居民代表大会、居民议事会、三方联席会等“三个会议”，解决了电瓶车停车挡道、口袋公园修复、老旧小区改造等58个实际民生需求问题。社区创新联系服务群众机制，落实1-5星级“敲门行动”，对独居、残疾等五星级人员每周一访，结合疫苗接种、防疫包发放等暖心实事，严格落实上门走访，织牢织密民生福祉的“保障网”。此外，社区以“社区公约”为抓手，广泛动员居民参与“千家共订约、万人共履约、人人可评约”的“三约”活动，每年开展“星级楼道”和“十大最美人物”评选，激励弘扬先进，传递正能量。\n南肖埠社区的基层群众性自治组织通过一系列创新举措，不仅提升了社区服务的质量和水平，还增强了居民的归属感和认同感，为构建和谐社会贡献了积极力量。社区的自治实践为其他地区提供了宝贵的经验和参考，展现了基层治理的新风貌和新成效。"
