        "summary": "该社区是浙江第一个地方党组织的诞生地，是毛主席视察过的第一个居委会，镌刻着党和国家领导人的为民情怀。社区共有居民住户3661户，常住人口1.08万人。先后获评世界卫生组织授予的“健康社区”、全国先进基层党组织、全国学雷锋志愿服务“四个100”先进典型——最美志愿服务社区等荣誉。\n近年来，社区党委牢记复信嘱托，组建“循迹讲师团”“红色宣讲队”“红领巾宣讲团”，创新“三式三促”主题党日模式，把“学红巷精神、做红巷传人”作为党员政治生活必修课和新班子、新党员、新社工第一课，全面撬动党员学习新活力，每年承接各类现场教学2000余次、35万余人。深化“上门看、当面谈、马上干”民情联系机制，打造红巷幸福邻里坊、红巷生活馆等8000余方党群服务矩阵。依托红巷党建联建，释放53家共建单位活力，为老人提供健康诊疗服务，开设共享食堂、四点半课堂，让“一老一小”幸福无忧。坚持共建共治共享，书记领着班子干，区域联动协同干，党员带着群众干，打造人人参与、人人享有的社区治理共同体。建立“红巷议事会”协商机制，居民的事让居民商量着办，完成16万方旧改项目，让2700户居民圆了“旧改梦”，成功创评“全省首批现代社区”，高分获评“浙江省第二批未来社区”。借着数字化改革“东风”，创新推出“独居老人安全守护一件事”应用场景，与老人共享“数字红利”。总结提炼“红巷老舅妈”协商自治、“红巷金牌管家”物业管理、“多彩公益”五社联动等社区党建工作十法，以“党建红”绘就美好社区新图景。"
