        "summary": "2009年，遂昌县（求和）人民调解委员会正式创立，2020年完成社会团体改制。“平安丽姐”娟姐工作室作为该调解委员会下属核心工作室，于2020年6月由遂昌县妇联、遂昌县司法局联合授牌成立。工作室聚焦妇女儿童权益维护核心使命，组建以女性为主体的专业调解队伍，整合法律、心理等多领域专家资源，创新推出24小时响应机制、上门调解等暖心服务模式。深耕矛盾化解一线，工作室成功调处婚姻家庭、劳动争议、交通纠纷等各类案件数百起，调解成功率达96%以上；同时常态化开展普法宣讲、权益帮扶等惠民活动，从源头化解风险、筑牢平安根基。凭借显著的社会成效与扎实的服务实绩，工作室先后斩获全国维护妇女儿童权益先进集体、全国三八红旗集体等国家级荣誉，成为群众信赖依靠的“知心娘家”。"
