        "summary": "云和县“老李帮忙团”成立于2010年7月，老李帮忙团成立以来，始终坚持弘扬奉献、友爱、互助、进步的志愿精神，秉承“帮助别人、快乐自己”理念，用爱心奉献社会，以真情服务群众，开展志愿服务活动。在“扶贫帮困、综治维稳、法律援助、纠纷调解、医疗卫生、食品安全、禁毒宣教、家政便民、精神慰籍”等方面，为群众提供卓有成效的便捷服务。每年有4000多志愿者，参加帮扶服务3000多次，受益群众超12万人次，“有困难找老李”成为云和县城广大群众的口头禅。该组织获得全国先进基层党组织、第四、五届浙江慈善兴志愿服务奖（团体、个人）、浙江省最美老干部（团体）、浙江省最佳志愿服务组织、浙江省先进基层党组织、浙江省服务型基层党组织建设百例特色品牌等荣誉。"
