        "summary": "鼓楼区东街街道军门社区组建于1952年，地处福州市中心繁华地段东街口 ，辖区面积约0.18平方公里。现有楼院68座，常住居民约3380户，人口1.2万余人。社区党委现有15个党支部，330多名党员，与42家单位开展党建联建，先后获评“全国先进基层党组织”等180多项荣誉。\n习近平总书记曾三次莅临军门社区调研指导，并作出“三个如何”重要指示。军门社区认真落实指示精神，巩固深化“13335”工作法，走出一条社区治理新路子。坚持深化党建引领，健全“五共”机制，率先建成“两中心两厅一平台”，首推“无假日社区”等机制，让群众生活和办事更方便。社区运用鼓楼区“两会一员”机制，组建社会治理市民委员会，成立“法务特派员”工作站，首创“居民恳谈日”，让群众表达诉求渠道更畅通一些。聚焦“军门一刻钟幸福圈”建设，探索智慧化服务治理模式，创办“长者食堂·学堂”、公办少儿托管中心和“四点钟学校”，成立社区线上图书馆，推行安防机制，打造“军门幸福里”社区服务综合体，满足居民多元需求，让群众感觉更平安、更幸福。"
