        "summary": "临川区西大街街道西大街社区地处老城区中心，成立于1978年7月，辖区面积0.23平方公里，居民3308户8392人，其中常住老年人1200余人、失能半失能老人约400人。社区先后获得全国示范性老年友好型社区、全国巾帼文明岗、全省幸福社区等荣誉称号。\n社区聚焦老年人多元化需求，创新养老服务模式。2021年，社区以公建民营模式引入颐福苑养老机构，运营1300平方米综合养老服务中心，设置助餐食堂、文娱活动室、26张养老床位，提供助餐助浴、康复护理等一站式服务。同时探索“三入四嵌一床位”居家养老模式，配套智能监测设备实现精准照护。\n    社区还打造“时光益站”志愿服务平台，联动抚州市开放大学开设老年学堂，构建起“机构养老+居家养老+志愿服务”的养老服务体系，让老年人乐享幸福晚年。"
