        "summary": `为构建“平安值夏、法制值夏”，维护社区和谐稳定，有效解决居民群众之间的矛盾纠纷，值夏社区居委会于2017年3月份成立了首个以个人命名的调解室——“白保忠调解室”，健全了相关制度，配齐配强了一批能力较强的人民调解队伍。共有调解员9名，法律顾问1名。通过多年的调解工作，总结出了一套自己的调解工作法即“123”调解法（1是第一时间介入；2是把握两个原则即实事求是和态度诚恳的原则;3是抓住三个关键点即抓住焦点，抓住要点，找出准利益平衡点）。在调解过程中，“白保忠调解室”始终秉着“公正+廉洁+依法、热情+真诚+耐心”的态度，使调解工作深得社区居民群众的认可，不仅妥善调解了各类纠纷，还有效的化解了矛盾双方的积怨，真正做到了为群众化怨言，帮邻里添和谐，搭起党群“连心桥”，构筑干群“和谐墙”。今年以来共调解纠纷40余起，调解成功36起，如今，社区居民遇到问题首先想到的就是“白保忠调解室”，这里已成为大家的“解难所”、“说事室”和“倾诉屋”。为此白保忠调解室2018年获得了省调解先进集体的荣誉。2020年获得青原区“十佳服务品牌”，2023年获得全国模范人民调解委员会等荣誉。`
