        "summary": "南昌市西湖区南站街道铁路二村社区位于南昌火车站旁，是铁路生活区的中心区域，由省委组织部挂点帮扶，先后获评全国先进基层群众性自治组织、全国最佳志愿服务社区等30余项荣誉。社区聚焦 “一老一小” 开展文明实践活动，作为西湖区“幸福时光养老服务互助平台”试点，依托“老铁志愿联盟服务队”，其志愿者队伍汇聚食堂、养老院、学校、卫生院等多个领域力量，共计 278 人，累计服务时长超6000小时，获评西湖区 “幸福时光” 优秀服务团队；同步打造 “老铁食堂” 助餐点，为1300余户居民提供优质餐饮服务，养老服务成效显著。针对学龄儿童家庭需求，社区打造 “幸福家驿站・鹿鸣成长园” 家校社协同育人平台，已举办各类主题活动38场，覆盖200余户学龄儿童家庭，有效构建协同育人生态。社区文明实践相关经验做法被各级广泛报道，成为基层服务标杆。"
