        "summary": "东营区文汇街道中山社区成立于2005年，服务10个居民小区、6121户、1.3万人，直管党员597名。曾荣获全国先进基层党组织、全国和谐社区建设示范社区、全省干事创业好班子等荣誉称号。\n建组织，让治理根基更加牢固。社区党委着力建强组织体系，推动所有小区成立党组织，选聘“退休能人”担任书记，实现党支部书记与业委会主任“一肩挑”。引导在职党员报到，培育红色楼栋长、党员中心户，推动党组织向下延伸。提服务，让资源力量更加高效。创新社工下沉治理机制，细分微网格，明确职责与资源清单；推行警社联动，创办社区警校，治安警情显著下降；引入社会力量打造“幸福合伙人”模式，年开展多样化活动600余场。破难题，让幸福家园可感可及。务实破解治理难题，强化党组织对物业的监督评价，推动物业更换与设施改造，居民投诉率大幅下降；运用智慧平台提升安全巡查效率；联动部门解决用水、停车等民生问题，切实提升居民幸福感。"
