        "summary": "南塔社区位于鄂州市鄂城区凤凰街道，占地面积约1平方公里，下辖69个小区、17个网格。现有户籍人口14000人（6531户），常住人口9728人，其中少数民族25人，60岁以上居民4729人。社区党委下设22个党支部，共有党员413名。\n社区在全省率先成立民族工作服务站，开办国家通用语言培训班，组织各族群众成立“荆楚石榴红”志愿服务队，参与公益活动，推动各族群众携手共建幸福美好家园。聚焦老年人实际需求，系统性优化适老环境、拓展为老服务项目，并积极发展老年志愿者队伍，鼓励老年人参与社区治理，实现“老有所养、老有所医、老有所为、老有所乐”。\n社区先后被授予“全国民族团结进步模范集体”“全国示范性老年友好型社区”荣誉称号。"
