        "summary": "三清社区位于黄州城区北面，常住人口9700余人，其中60岁以上老人1740人。2017年社区以居家养老试点为契机，投资140余万元建成1000平方米的居家养老服务中心，设有多功能服务区，为周边老年人提供生活照料、医疗保健、文化娱乐等综合服务。\n社区着力构建网格化助老服务体系，引进专业机构，并联合党建联盟、卫生服务站及周边商户，整合资源提供健康管理、心理疏导、便民优惠等多样化服务。通过培育老年社团、开展志愿助老活动，形成老年人自我服务与社区支持相结合的良性机制。\n经过持续探索，社区居家养老服务已成为基层治理的重要品牌，有效提升了为老服务能力与水平。2021年10月，社区获评由国家卫生健康委、全国老龄办颁发的“全国示范性老年友好型社区”称号。"
