        "summary": "广北社区隶属湖北省潜江市广华寺街道，2019年10月成立，辖7个小区，60岁以上老人4789人、占比46%，老龄化程度较高。\n社区聚焦老年群体需求，以两大便民服务站为支点，构建 “阶梯互助+日间照料” 养老服务体系，打造“医、食、养、陪”一体化居家养老服务中心，为老年特殊群体建立专属档案、专人跟进。依托社区卫生站点提供上门康复服务，升级1800平方米养老活动中心，配套无烟食堂、棋牌室等设施；组建“银发志愿服务队”，运用“码上办”智慧平台+网格员入户排查，全方位保障老人生活。\n社区先后荣获“全国示范性老年友好型社区”“潜江市抗击新冠肺炎疫情先进集体”“全市先进基层党组织”等荣誉。"
