        "summary": "园林街道红庙社区成立于2003年，地处潜江主城区，社区党委下设5个党支部，现有直管党员209名，总住户10601户，人口25013人，涵盖25个小区、26个单位，划分八个大网格，细分16个小网格进行管理。近年来，社区坚持以党建工作为核心、以服务居民为重点、以维护稳定为基础、以居民满意为目标，创立了李焕森名书记工作室，打造党员教育实践新平台，为社区可持续发展注入活力；创建了名筑仕嘉小区“党建引领，三治融合”基层治理特色品牌；创建了清廉小区，开办了纪法学堂，筑起廉政清风的治理堡垒；组建了潜城馨家，推动“两企三新”党组织建设，强化了党组织的凝聚力和战斗力，促进了社区经济的多元化。\n社区先后被评为“全国和谐社区建设示范社区”、“全国创建学习型家庭示范社区”、“湖北省先进基层党组织”等荣誉称号。社区书记李焕森同志也先后获评“全国优秀党务工作者”“全国抗击新冠肺炎疫情先进个人”“第四届湖北改革奖（个人奖）”等荣誉，并多次受到习近平总书记等党和国家领导人亲切接见并合影留念。"
