        "summary": "洪山区珞南街道丽岛花园社区成立于2003年1月，坐落于珞狮路南湖畔，现有居民1689户、3960人，下辖丽岛花园和丽岛紫园2个小区，是一个配套完善的纯商住型现代化社区。社区现有工作人员9人，“两委”成员6人、社区干事3人。\n社区以党建为引领整合辖区资源，构建“资源联动品牌服务”运作模式，联合高校打造“丽岛健康π”等系列ip项目，建立“党员带头、志愿协同、居民参与”的常态化体系，推动23部电梯完成更新改造，培育社区特色文化平台，通过“草地读书会”等活动促进邻里融合。\n社区先后荣获全国文明单位、全国和谐示范社区、全国示范住宅小区、全国防灾减灾示范社区等多项荣誉。"
