        "summary": "天兴花园社区位于武汉长江新区谌家矶街道兴盛路201号，于2014年4月成立，是一个保障性住房集中居住小区。\n针对所住居民老年人多、孤残人多的特点，社区在防灾减灾工作中坚持“两结合、两便利”原则，即防灾减灾队伍组建与辖区单位相结合、避难场所设置上小区绿化广场与学校操场相结合，既便利居民群众疏散，也便利防灾队伍施救。\n目前已组建150人志愿者队伍，每年开展6次消防演习，配置应急器材和物资，不定期组织减灾教育活动和安全检查，针对性制定各类灾害应急预案及一对一、多对一应急结对帮扶计划，形成了横向到边、纵向到底的救灾工作责任体系。\n2015年、2016年分别成功创建市级、省级综合减灾示范社区。2021年成功创建全国综合减灾示范社区。"
