        "summary": "李家湖社区坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻新时代文明实践要求。社区坚持以党建为引领，健全社区党委统筹、网格协同、居民参与的治理体系，持续深化“梦想家公社”党建品牌建设。\n社区紧扣民生需求和文明创建要求，统筹推进便民服务、文明实践、志愿服务和基层共建。常态化开展公益课堂、亲子活动、科普教育；依托“侨胞之家”，将为侨服务融入社区治理和文明实践，拓展文化交流、志愿服务和公共服务内容，持续提升社区环境品质、居民参与度和治理效能，逐步形成共建共治共享的文明创建新格局。\n社区先后荣获第六届全国文明单位，“省级文明单位”“省科普惠民社区”“省级充分就业社区”“市级文明社区”“全市为侨公共服务体系示范单位”等荣誉称号。"
