        "summary": "七里新村社区位于宜昌市东大门猇亭区，是一个以搬迁农民集中安置为主体的新型城市社区。现有居民1700余户、4800余人，党员141人，下设6个网格党支部，构建“社区党委—网格党支部—楼栋党小组—党员中心户”四级组织架构，吸纳9个共建单位参与治理。社区以党建引领为核心，创新推行“五社联动”机制、“红色楼栋管家”等制度，培育朝夕公益志愿者联合会等26个社会组织，建立积分驿站激励机制，带动近2000名居民参与治理，形成了党建引领组织共建、资源共享、社会共治、活动共办、难题共解的基层治理新格局。先后获评“全国和谐社区建设示范社区”“全国民主法治示范社区”、全省社区党支部“十面红旗”等荣誉。"
