        "summary": "荷花池社区地处长沙松桂园商圈核心区，0.3平方公里的土地上承载着1.2万居民的生活烟火。社区党委下设7个党支部（含1个非公党支部），直管党员273名，辖区聚集省妇幼保健院、长沙市第一医院、新湖南大厦等多家企事业单位及商业综合体，还有市直幼儿园、省直小学、国家级重点中职学校组成的教育矩阵。\n近年来，社区党委以“网格+支部+协会+项目”模式为抓手，打造基层治理特色品牌，用精细化服务让老城焕发新活力。“全国和谐示范社区”、“全国妇联基层组织建设示范社区”、“全国三八红旗集体”、“湖南省文明社区”、“湖南省流动妇女平安之家”、‘“湖南省巾帼文明岗”等30多项市级以上荣誉称号。\n作为全国三八红旗集体，社区挖掘辖区优秀妇女代表，组建“荷映红”巾帼工作室，构建“5+N”服务体系：思想引领站开展主题宣讲，创业就业站链接资源助女性创业，法律援助站提供维权服务，公益服务站组织帮扶活动，家庭教育站开展亲子课程。工作室成立以来，已为妇女儿童解决实际困难300余件，用“她力量”筑牢民生保障网。"
