        "trueName": "湖南省长沙市天心区新开铺街道桥头社区-全国先进基层群众性自治组织",
        "summary": "长沙市天心区桥头社区成立于2001年，辖区面积1.2平方公里，服务居民约1万人。社区党委下设7个党支部，直管党员290名。\n社区以党建为引领，规范提升党群服务中心及5个服务站，联动社会组织精准服务“一老一小一困”。依托智慧平台深化网格治理，编印便民指南，引入健康、健身设施便利居民。健全片组邻“三长”工作体系，组建多支志愿队伍常态化开展平安创建。党建引领红色业委会与物业协同，有效推进老旧小区改造及城市更新，并依托社区慈善基金筹集近50万元款物帮扶困难群体。\n社区获“全国先进基层群众性自治组织”“湖南省和谐示范社区”等多项荣誉，是首批国家级社区青春行动优秀实施点，涌现党贾、何佩君、章筱西等先进典型。"
