        "summary": "学堂坡社区位于岳麓山大学科技城核心区域，是典型的老旧城区开放式社区，辖区面积1平方公里，常住居民1.1万人。现有3个党支部，72名党员，有湖南师范大学6家驻社区单位，共青团长沙市委等37家联席单位，获评全国先进基层党组织等荣誉，组织编写出版《党建引领新型社区治理——学堂坡社区工作实录》，得到学习强国等平台多次推荐好评。\n近年来，社区坚持政治引领、德治融入、法治保障、群众自治、智治支撑“五治”融合治理模式，在深化党组织建设与基层治理“一体四化”格局的基础上，搭建了“逢四议事”平台，建立“社区-片-组-邻”四级网格，先后组建580志愿服务队等25支特色团队，打造社会组织公益园，培育发展南音心房社工服务中心等11家社会组织开展精准地专业服务，选配“三长”等六支队伍，有效实现了“横向到边、纵向到户、靶向到人”的无缝衔接，切实将街道“146”治理体系走深走实。"
