        "summary": "资新社区共居民1145户、户籍人口2330人，其中60岁以上居民达818人，是邵阳市人口老龄化程度最高的社区。该社区于2019年10月成立“资新玖玖红”志愿服务站，以此为抓手全方位推进为老服务工作。一方面丰富精神文化生活，培育唱歌班、舞蹈队等8支文艺团体，建设200余平方米“美在金秋”老党员之家，常态化开展趣味手工、文体运动及传统节日邻里互助活动；另一方面完善便民服务体系，推出“玖玖红”银发食堂、助老送餐等暖心项目，针对特殊群体落实“5个到户”，成功构建起“15分钟便民服务圈”。该社区于2020年获评省级最美文明实践志愿服务社区，2021年获评全国示范性老年友好型社区，2022年获评全国“四个100”最佳志愿服务社区，2023年获评省级充分就业星级社区。"
