        "summary": "深圳市宝安区西乡街道人民调解委员会是西乡街道直属的人民调解组织，现有专职调解员16名，兼职调解员78名，业务范围涵盖民事纠纷调解领域，曾于2020年获评司法部“全国模范人民调解委员会”称号。该调委会开创性的推出了“说事评理”人民调解模式、固戍议事阁等特色调解品牌，其中“说事评理”人民调解模式成绩尤为突出，2019年荣获宝安区最佳社会治理创新典型案例，2021年获评宝安区市域社会治理现代化十大优秀案例，2023年获评宝安区坚持和发展新时代“枫桥经验”十大优秀案例，并以其创新性、引领性和典型性在基层社会治理现代化建设中发挥重要作用，成为全区唯一入选2021年广东省首批法治政府建设示范项目。"
