        "summary": "益田社区是深圳市典型的超大型城市社区，总面积0.42平方公里，居住人口3万余人。社区以党建引领为核心，深入实施“家园党建”计划，推动实现党组织在小区和党员在楼栋“双100%覆盖”。通过探索“党建+服务”“公益+运营”新路径，打造24小时图书馆、政务服务、志愿服务三张名片，引进140家社会组织，链接公益服务活动超3000场。依托党员服务市集、居民议事会精准对接需求，精心培育“家园荟·好邻帮”项目，累计服务居民1.2万人次，荣获深圳市关爱行动“年度市民满意项目”。社区先后荣获全国示范性老年友好型社区、全国先进基层群众性自治组织、全国文明实践巾帼志愿阳光站等5项国家级荣誉及20项省、市、区级荣誉。"
