        "summary": "在上级党委机关部门坚强领导及各级司法部门大力支持下，深圳市福田区莲花街道景田社区全面落实法治责任，勇担法治尖兵使命。依托“小网格”常态化机制，凝聚多方力量，深化网格化管理，让“枫桥经验”在社区持续深化，切实做到社情民意零遗漏、为民服务全覆盖、全域管理无盲点，成功营造了彰显公平正义的民主法治环境，构筑起“与法同行、法在心中”的社区法治建设图景。在不断提升居民获得感、幸福感、安全感的同时，也取得了一系列标志性成果：2014年建成全市首个社区法治主题公园，并荣获省级“法治文化主题公园”称号；2015年成功创建“全国民主法治示范社区”；2018年，全力打造的普法基地福景外国语学校获评省级“青少年法治教育实践基地”。"
