        "summary": "翰岭社区位于深圳市福田区梅林街道，面积0.7平方公里，常住人口1.6万，是广东最大清真寺所在地，聚居壮、回、维吾尔等32个民族同胞近千人。社区以“籽籽同心·幸福翰岭”品牌为引领，创新“四化四心”工作法，即以精准化服务管理知人心、以精细化支持帮扶聚人心、以均等化公共服务暖人心、以法治化权益维护安人心，建立党建联建、就业创业帮扶等机制，实现各族群众“留得住、融得进、过得好、发展强”。\n近年来，翰岭社区获评“全国民族团结进步示范社区”，并作为“全国构建互嵌式社会结构和社区环境现场推进会”唯一社区观摩点，荣获深圳市“民族团结进步互嵌式示范社区”、首批“榴深服务站”“年度爱心社区”等称号，成为超大城市民族工作样板。"
