        "summary": "胜和社区面积4.37平方公里，户籍人口约7800人，下辖17个居民小组，其中16个有经济组织。\n胜和社区蕴藏着丰厚的历史文化，被考古学家誉称为“珠三角第一村”的蚝岗贝丘遗址，5000年前已有古人类在这一带聚居。\n东莞市新城市中心区的发展给胜和社区带来机遇，标志性建筑物有东莞市行政办事中心、东莞市体育中心等。由联益、恬甲村民小组自建的银丰路，聚合多家各省风味的餐饮业，被誉为不夜天的“中华风味美食街”。社区和小组两级兴建有众多的综合楼、商住楼和住宅楼。\n胜和社区先后荣获全国和谐社区建设示范社区、全国综合减灾示范社区、省宜居社区、省科普示范社区、省卫生社区、省民主法治示范社区、省“六好”平安和谐社区等荣誉称号。"
