        "summary": "江翠社区辖区面积0.45平方公里，常住人口2659户、7184人，是大型老旧开放社区。社区党委设7个党支部，现有党员103人，近50%为厂企退休党员。社区现有工作人员9人，其中“两委”干部6人、专职网格员3人。近年来，江翠社区充分发挥社区党委的政治引领作用，创新“1+3+N”社区治理模式，即打造1个总面积达2000平方米的公共服务载体，建强智慧网格小组、社区居民“议事委员会”和社区居民“志愿服务委员会”等3支服务队伍，以群众需求为导向，打造N种服务平台，推动社区服务项目化、精细化、智能化。充分发挥社区作为全国、全省基层立法联络单位的优势，组建立法意见义务收集员队伍，常态化开展“民意直通车”活动，展现全过程人民民主生动实践。社区先后荣获全国文明单位、全国巾帼文明岗、广东省文明社区、江门市先进基层党组织、江门市基层党建示范社区等荣誉称号。"
