        "summary": "江南街道仁美社区成立于2002年，是新旧融合型社区。近年来，仁美社区党总支充分发挥核心作用，统筹资源力量、创新方式方法，聚焦辖区老年人和青少年的需求，深入开展“一老一少”精细化服务，扎实推进基层治理精准化水平，创新打造“幸福·耆少”仁美社区品牌，系统推动为社区服务能力与品质双提升。\n一是擦亮“国字号”老年友好型社区品牌，统筹资源力量，构建“网格特色化、管理精细化、服务全方位”的长者服务新格局；二是连续14年开展“七彩桥”少年助长服务项目，每年开展活动超20场次，受惠群众超过3.5万人次；三是整合资源改造下沙公园、实施老旧小区改造、燃气入户等项目，打造宜居环境，让“一老一少”舒适、舒心。\n在社区党员群众大力支持下，先后获得全国综合防灾减灾示范社区、全国示范性老年友好型社区、广东省友好儿童示范社区、广东省最美志愿社区、江门市党群服务优秀项目等58项荣誉。"
