        "summary": "象山区同心社区位于桂林市区东南部，隶属于桂林市平山街道辖区，东临漓江和同心村，西邻瓦窑加油站，北靠同心村。成立于2002年8月，辖区面积1.9平方公里，管辖13个居民小区：鑫隆置业广场、燕兴公司宿舍、同心路2号、3号居民小区、同心路5号油脂厂宿舍、同心路7号烟贸宿舍、鑫隆苑、漓江花园、同心园小区和惠龙世纪城等居民小区。居民住宅楼117栋，住户3450户，居民8800人左右，社区党委下设4个党支部，现有党员266名。辖区无大型企业和单位,是以汉族为主的商住型纯居民社区。\n多年来，同心社区以全国综合减灾示范社区为标杆，坚持“预防为主、防治结合”的工作方针，构建起“党建引领、网格联动、多方参与”的减灾工作格局；创新“科普+体验”宣传模式，通过减灾知识讲座、应急技能培训、沉浸式灾害模拟体验等活动，让防灾减灾意识深入人心，全面提升居民防灾自救能力，成功获评全国综合减灾示范社区。"
