        "summary": "桂林市七星区漓东街道五里店社区成立于2021年3月，总面积约1.5平方公里，常住人口约9886人。社区党委下设10个党支部，共有344名党员。辖区共有8家企事业单位及学校。近年来，五里店社区坚持党建引领科建，深入贯彻以人民为中心的发展思想，大力践行科技为民、科普惠民理念。秉承“传播科学思想”“普及科学知识”“弘扬科学精神”“倡导科学方法”的宗旨，以创建“国家科普示范社区”为抓手，创新“党建+科普”模式，构建“四心”“四化”基层科普工作体系，通过“党旗领航 五彩课堂”项目，围绕科普所长、基层所需、群众所盼，开展主题性、群众性、持续性、趣味性于一体的系列科普活动，构建社区科普教育生态圈，全面促进社区科普教育成果全民共享。2022年社区荣获“自治区防灾减灾示范社区”称号。"
