        "summary": "九岗岭社区成立于2001年6月，位于风景优美的两江四湖湖畔，辖区面积23.5万平方米，东起榕湖迎宾桥、红桥，南临桃花江，西至湘桂铁路，北接丽君路，是广西和桂林市社区建设试点社区之一。现有居民3079户，9168人。社区党委下设8个党支部，在册管理党员254名。辖区有榕湖酒店管理集团、秀峰区丽君社区卫生服务中心等单位，是一个老旧无物业管理辖区。社区党委坚持“党建为民 文化惠民”的理念，打造九岗岭之夜、书香秀峰读书角、欢乐广场、星空影院、翰墨光影、居民学堂、邻风物语等一批文化惠民项目。社区先后2012年全国综合减灾示范社区、2012年国家级充分就业示范社区、2024年自治区三星级党组织、2023年桂林市“清廉社区”等50多项荣誉。"
