        "summary": "钦南区文峰街道三宣堂社区地处钦州市历史文化街区，总面积0.65平方公里，辖14个居民小组，常住3017户8879人，划分6个网格管理。2002年，因辖区内坐落着民族英雄刘永福旧居三宣堂而更名，历史文化底蕴深厚。社区紧扣老年友好主题，打造1400余平方米的开放式功能室，建成300多平方米的“金秋家园”，盘活“红网格、红景点、红马褂”特色资源，打响“三红社区”“五老五就近”特色品牌；通过“街居吹哨、五老报到”工作机制，激活老年群体参与社区治理的内生动力。此外，借力“钦点即到”“随手拍”等智慧载体，精准对接民生需求，成功探索出一条“党建引领、多元协同、智慧赋能”的基层治理新路径。近年来，先后获评“全国示范性老年友好型社区”“全国红十字模范单位”“自治区民族团结进步示范社区”“五星级党组织”等十余项市级以上荣誉。"
