        "summary": "钦南区文峰街道文昌社区，面积4.5平方公里，辖21个居民小组，常住3611户15073人，划分7个网格治理。社区坚持党建联建共建，以“一盘棋”思维强化组织引领，以“一张网”模式全覆盖网格治理，以“一条心”理念凝聚共建合力。依托党群服务中心，高效完成平陆运河（钦南段）沿线土地征搬工作。利用“桂志愿”平台推行“社区吹哨，志愿报到”机制，发展志愿者1300余人。打造“邻里互助”“妈妈文艺队”“小韦说事”等品牌，健全综治中心、工会驿站、暖‘新’驿站、零工市场等载体，吸纳“红骑手”融入基层治理，以社区治理现代化增进民生福祉。近年来，先后获评“全国综合减灾示范社区”“国家级充分就业社区”“全国民族团结进步示范区”“全国最美志愿服务社区”“第七届全国文明单位”等国家级、自治区级荣誉40余项。"
