        "summary": "榕山社区成立于2002年10月，辖区面积约1.46平方公里。辖区人口总户数9280户，常住人口户数8632户，常住人口25922人。目前辖区共有18个居民区，共有党员243名。\n近年来，社区以“以人为本、服务群众”为宗旨，坚持以“预防为主”的方针，努力打造安全宜居生活环境，着力在解决居民实际困难上用功着力。多次组织工作人员对辖区内易发生地质灾害和雨天易涝的地段进行巡查。如2025年5月27日，为切实做好地质灾害防范工作，保障人民群众生命财产安全，榕山社区紧急召开强降雨防御工作布置会，及时对有山体的小区张贴安全警示标识，离山体近的住户挨家挨户提醒居民暴雨天加强防范，遇到问题及时向社区求助。并动员房屋存在安全隐患的居民投亲靠友，搬离隐患居住点，提前做好防护措施。同时在居民微信群发送温馨提示，得到居民一致好评。2019年社区获得“全国综合减灾示范社区”荣誉称号。"
