        "summary": "漓东街道毛塘路社区成立于2002年8月，位于环城南一路16号，东抵桂磨路，南至宜祥路，西临骖鸾路，北接五里店路。现有常住户4566户，总人口6632人，其中有壮、瑶、回、仫佬等12个少数民族，占总人口约15%。社区立足“老人多、孩童多、少数民族多”的实际情况，打造“党旗领航 和谐毛塘”品牌，以铸牢中华民族共同体意识为主线，聚焦“一老一小”及民族融合，创新开展关爱服务。社区创建了七星区首个铸牢中华民族共同体意识实践教育基地，培育了“中华民族一家亲系列文体活动”、暑期兴趣班、“非遗课堂”及“互帮互助协会”等特色项目，积极营造“老有所养、幼有所教、族有所融”的社区氛围。近年来，先后荣获全国和谐社区建设示范社区、全国民族团结进步模范集体、全国示范性老年友好型社区等多项国家级荣誉。"
