        "summary": "将军桥社区位于桂林市区南部，因辖区南溪河上原有将军桥而得名，总面积约2.6平方公里，常住人口13000余人。社区党委下设9个支部，有党员398名。辖区内自然风光秀丽，城市功能完善，人居环境和谐。社区驻有部队、医院、学校等多家机关企事业单位，460多家民营企业、个体工商户在社区创富发展，社区教育、医疗、餐饮、娱乐休闲等功能一应俱全，是象山区名符其实的“宜居、宜业、宜学、宜商、宜游”社区。\n社区党委认真学习贯彻习近平新时代中国特色社会主义思想，以建设和谐宜居、充满活力、文明幸福的近悦远来社区为目标，强化党建引领、服务群众、社区治理，不断增强社区党委组织功能，有力地促进了社区各项事业的进步：先后获得了全国和谐社区建设示范社区、全国民主法治示范社区、全国科普示范社区、全国学雷锋志愿服务“四个100”先进典型最美志愿服务社区等多项荣誉称号。"
