        "trueName": "海南省文昌市龙楼镇航天社区－全国文明单位、全国综合减灾示范社区",
        "summary": "2007年，文昌航天发射场项目开始征地建设，涉及龙楼镇星光、龙楼两个村委会和东郊镇中山村委会。项目建设搬迁后撤销星光村委会，于2012年4月24日重新设立航天社区居委会并组建党支部。社区占地约1500亩，下辖10个居民小组834户3541人，“两委”干部8人，其中党员6人，党支部党员54名。\n社区以党建为引领，促发展保就业，实现商铺全招租，引进养老企业带动分红与就业，成立就业服务中心助力劳动力转移，联动发射基地提供岗位。促稳定保平安，抓实疫情防控、火箭发射保障、治安巡逻。促提升保共赢，加入航天大社区党建联盟，开展多样主题党日活动。\n社区曾获“全国文明单位”、“2017-2020年度平安中国建设先进集体”、“全国综合减灾示范社区等荣誉”。"
