        "summary": "塘沽街道地处天津市滨海新区核心区，是商贸、科研、金融服务的聚集区，有回族、维吾尔族等13个少数民族，下辖12个社区，常住人口2.5万户6.2万人，曾荣获“第十批全国民族团结进步示范街道”。\n坚持以铸牢中华民族共同体意识为主线，深化“新塘石榴红”民族品牌建设，依托街道综合文化站，高标准建成集教育基地、主题广场、风采长廊于一体的“1+2+2”民族工作阵地，即依托1个“互嵌式基地” 强化思想引领，打造“国旗广场、石榴籽广场”2个广场，传递团结信念、升华家国情怀，建设“石榴花红议事长廊、民族风采展示长廊”2个长廊，常态化开展各类特色活动，通过精准服务、文化浸润，讲好民族团结故事，共绘和美塘沽。"
