        "summary": "河西区下瓦房街道富裕广场社区成立于2002年，地处下瓦房街道核心商圈，辖区包括3个居民小区和2栋商务楼宇，常住人口1687户4128人，是一个商住交融、新老住户混居的混合型社区。\n多年来，社区党委以“红色微家”议事厅为载体，聚焦破解基层治理难题，推动垃圾分类、老旧管道改造等多项民生项目落实。通过定期举办“红色领家”接待日，组织党员、物业与居民共同协商环境优化、设施维护等群众关切的问题，同时整合辖区资源，协同多方力量，提升群众工作满意度，有效增强了社区凝聚力。社区先后荣获全国妇联基层组织建设示范社区、全国民主法治示范社区及全国文明单位等称号。"
