        "summary": "谊景村社区建于上世纪90年代初，常住居民1905户3943人，其中60岁以上老年人1513人，占比近40%。社区党委紧扣老年人需求，以提升群众满意度为工作的出发点和落脚点，不断增强党组织凝聚力。\n近年来，社区积极探索党建引领社区治理新路径，以“蔷薇工程”为抓手，深化“五微精治 无微不至”行动，不断提升网格化管理服务精细化水平。创新推出的“1+N帮1”助老服务模式，精准调研老年人需求，提供细致入微的服务。该模式先后入选“天津市精神文明建设创新项目”及民政部“100个优秀社区工作法”。社区曾获评全国和谐社区建设示范社区，社区党委荣获全国先进基层党组织、全国文明单位及天津市先进基层党组织等称号。"
