        "summary": "愉悦港湾社区位于芦台街道东北部，下辖9个区域，集老旧小区、零散楼栋、平房区等为一体。社区常住居民1862户3852人，党员95人。\n该社区大力实施“夜精彩”治理项目，设置12处照明设施，亮化文明实践广场，并联合宁河中医院、宁河区文化馆等20余个部门，举办文艺展演、中医夜市等助老爱老活动110余场，服务2000余人次。通过设立“积分超市”“积分存折”等形式，招募志愿者320余名，组建环境治理、文艺宣传等10支志愿服务队伍，常态化服务群众6000余人次。创新设立3处“幸福驿站”，集义剪、旧物置换、金融咨询等20余种便民服务功能于一体，累计服务居民达2400余人次。社区曾荣获“全国示范性老年友好型社区”荣誉。"
