        "summary": "西青区杨柳青镇御河墅社区成立于2013年，下辖2个小区，常住人口2154户5032人，60岁以上老年人772人。社区共划分6个普通网格。曾获评全国老年友好型社区荣誉。\n社区聚焦建强服务阵地，锻造“银龄先锋”，高标准打造老年友好社区。筑牢为老服务主阵地。依托社区服务阵地提供生活照料、健康监测等一站式养老服务。与西青中医院合作，开展“义诊进社区·服务暖人心”活动，为老年人提供免费医疗服务。乐享精神文化新生活。组建“俏江南”艺术团，开展“春风如你，熠熠芳华”文艺演出，开展智能手机教学，以科技赋能养老，助力老年人融入数字社会。汇聚银龄先锋正能量。鼓励有能力、有精力的老年人认领楼长参与社区治理，发动银龄力量调解邻里难事。"
