        "summary": "昆璞里社区成立于1995年，辖区面积0.163平方公里，下辖7个自然小区，常住人口2156户4996人，划分普通网格10个。曾荣获“全国综合减灾示范社区” 称号。\n昆璞里社区秉持“人民至上、生命至上”理念，以党建为引领，建立“社区—网格—志愿者”三级应急响应队伍，开展常态化拉网式隐患排查，一年内累计巡查超百余次，整改安全隐患20余处。同时，加大硬件投入与物资储备，汛期启动应急预案，部署防汛沙袋，执行24小时值守制，工作人员冒雨涉水解决群众需求，雨雪天气及时清整道路，保障居民出行安全。从制度建设到实际行动，从硬件完善到贴心服务，昆璞里社区用责任与担当守护居民群众生命财产安全，打造平安和谐社区。"
