        "summary": "官井湖社区位于麻江县城东南部，辖区面积2.01平方公里，划分12个网格，6个居民小组，总人口3904户12985人，其中易地扶贫搬迁移民1312户5674人。官井湖社区是一个集商住、易搬为一体的多元化治理新型社区，少数民族占比80%以上。县选派乡村振兴驻社区工作队1支，配备驻社区第一书记1名、队员2名；有社区工作者6名，专职网格员15名，支部党员61名。\n社区始终坚持党建引领，持续深化“三到社区”改革，不断夯实民主法治基础，着力提升治理效能。扎实推进“一中心一张网十联户”机制建设，建成法律服务援助室、阳光调解室等法治阵地，夯实基层治理基础。积极创新法治宣传方式，组建调解委员会与法治宣传队，依托院坝会及民俗活动等形式，拓宽群众说事议事渠道，促进民主决策与结果公开，有效增强居民自我管理能力和法治意识。在实践中逐步形成依法服务、管理民主、治理有序的社区治理体系，相关工作取得显著成效，于2022年被司法部、民政部授予“全国民主法治示范社区”称号。"
