        "summary": "栗坪社区是一个多民族聚居的易地扶贫搬迁安置社区，位于兴义市西南部，面积0.84平方公里。社区成立于2019年，有16个民族2672户12068人。社区致力于打造“四宜”（宜居、宜养、宜业、宜学）完整社区，配套建设了从益童乐园到日间照料中心的全年龄段服务设施，以及综合超市、理发店、社区食堂等商业便民设施，并引入95家企业，促进群众就业率达95%。同时，利用春节、端午等传统节日和“三月三”“六月六”等民族节日，组织开展各种形式的活动，增进各族群众交流交往交融。\n先后获评“全国脱贫攻坚先进集体”“全国示范性老年友好型社区”“全国民族团结进步模范集体”等荣誉。2025年，栗坪完整社区试点被纳入住房城乡建设部全国第三批完整社区建设案例集。"
