        "summary": "府后山社区成立于2002年1月，辖区面积约0.5平方公里，现有常住人口1531户3142人，社区党总支下设党支部3个，有党员97名，辖区内有机关企事业单位4个，大小商户53家，划分为8个居民网格小组，配备网格长8名、联户长48名。\n近年来，府后山社区以党建为引领，探索基层治理新模式，创建“党建+服务”特色品牌、创新“3+5+N红色服务方阵”、拓展“党员志愿服务”品牌。实施“同心共向、抓组织载体，同筑共建、抓品牌创新，同频共振、抓六共融合”的“三同三抓”工作模式，通过组织共联、网格共建、阵地共用、服务共享、活动共办、文化共创“六共”融合打造了红花岗区统战、侨胞之家、民族团结进步等示范点。以“五义工作法”（义学、义集、义诊、义言、义养）为指导，以“我为群众办实事”为抓手，将“真抓实干、务实为民”融入到日常工作中，结合“网格党建”开展扶弱助困、平安建设、健康卫生、民生工作等服务，成为了服务体系完善、管理有序、居住环境优美、治安良好、生活便利、社会风尚良好的和谐社区。\n社区先后荣获“全国文明单位”“省级文明单位”遵义市“先进基层党组织”“遵义市全面小康创建”市级示范社区等荣誉称号。"
