        "summary": "小坝社区于2005年5月成立，辖区面积0.46平方公里，居住着汉族、彝族、傣族等32个民族，7220户1.8万余人。近年来，社区党委坚持人民至上的治理理念，以铸牢中华民族共同体意识为主线，深入培育“幸福小坝‘家’文化”社区治理品牌。设立民族团结誓词碑，开展“续写民族团结精神”活动。整合资源，设立幸福食堂、蜂享驿站、多元邻里坊等服务。形成社区各民族居民学习教育、协商议事、文化交流的“互嵌式”和谐家园。近年来，先后荣获全国民族团结进步模范集体、全国先进基层群众性自治组织、全国最美工会户外劳动者服务站点、全国示范性老年友好型社区、云南省民主法治社区等荣誉称号。",
