        "summary": "七步场社区隶属昆明市呈贡区乌龙街道，已有600多年的历史，面积3.43平方公里，常住人口2100余人，流动人口1200余人。\n社区以党组织为治理核心，构建“党建引领、社企联动、居民参与”治理机制，推行“社区+公司+居民”治理模式。依托“青方臭豆腐”技艺打造特色治理抓手，以产业促治理，收益反哺民生，壮大豆腐产业带动600余人就业；建设标准化养老服务中心，解决老年人养老难题；调解矛盾纠纷，为特殊群体提供精细服务；改造提升人居环境，组建志愿服务队常态维护，实现“路净、院洁、景美”。\n社区先后荣获全国和谐社区建设示范社区、全国示范性老年友好型社区、云南省科普示范社区、春城先锋示范党支部等荣誉称号。"
