        "summary": "结莎街道下辖4个社区，辖区面积141.92平方公里，共10160户25469人，藏、汉、回、珞巴族等23个民族聚居。\n街道深耕基层治理，打造“一社区一品牌”党建特色，创新“六微六融”治理模式，推动党建与民族团结、民生服务深度融合，树立城市民族工作优秀典范，相关成效获自治区党委书记王君正及西藏自治区成立60周年中央代表团肯定，获评“西藏自治区民族团结进步多民族和谐街道”。\n疫情期间，街道筑牢联防联控防线，保障居民生活与社区稳定，嘎玛庆社区获评“全国抗击新冠肺炎疫情先进集体”。2025年，嘎玛庆、红星社区分别获评全区高原经济高质量发展、民族团结进步基层党组织示范点。同时，街道稳步推进项目建设与产业发展，集体经济年分红超800余万元。"
