        "summary": "老城街道鼓楼社区位于安康市老城区，辖区0.85平方公里，聚居着回、汉、白、维、满等多民族群众2946户，10866人，其中少数民族占总人口54.7%，是全市最大的少数民族聚居区。社区有4条大街、8条小巷、22个小区（家属院）、4座清真寺与7个机关单位，划分9个大网格。共有党员154名，下设5个党支部。\n社区紧扣“加强民族融合 建设孝义鼓楼”党建品牌，以“一老一小”为核心关切、“居家养老”为抓手，推动“十助”服务落地，最终锚定“美在社区、爱在社区、安在社区、乐在社区、和在社区”的“五在”目标，让各民族群众的归属感、获得感、幸福感在基层治理中持续升温。社区已先后获得全国民族团结进步示范社区、全国民主法治示范社区、全国示范性老年友好型社区等国家级荣誉。"
