        "title": "全国和谐社区建设示范社区、全国综合减灾示范社区",
        "trueName": "陕西省西安市新城区韩森寨街道咸东社区－全国和谐社区建设示范社区、全国综合减灾示范社区",
        "summary": "咸东社区位于咸宁东路531号，辖区面积约0.42  \\t \" 平方公里。下辖9个院落，4108户，5380余人。\n近年来，咸东社区着力推进社区基层治理体系建设，坚持党建引领为核心，共驻共建为纽带，从探索新时代“枫桥经验”的新城实践出发，初步形成“咸东小哥1+5+N”三维体系基层治理模式，并将“群众满意”纳入治理机制,统筹推动物业服务管理和基层社会治理紧密融合。“咸东小哥”志愿队全年持续进行平安巡逻、环境整治、助残帮扶等志愿活动，且多次被主流媒体报道。《党建引领融资源 咸东小哥添活力》入选中国共产党员网先进典型社区案例。咸东社区先后荣获“全国先进基层党组织”“全国和谐社区建设示范社区”“全国综合减灾示范社区”等国家级表彰7次，省市级表彰100余次。"
