        "summary": "一、基本情况\n新园社区位于火炬路五号院内，面积0.4平方公里，下辖5个院落，64栋住宅楼，4428户9650人。划分5个基础网格，1个专属网格，专兼职网格员48人，驻地企业单位5家。现有社区工作人员13人。\n二、主要工作成效\n联合各驻地单位常态化开展消防安全知识培训、高层逃生演练活动十余次；每年防灾减灾日，开展防灾减灾知识宣传活动，提高居民安全意识；联合物业开展消防排查整治与清理行动，杜绝安全事故发生；定期开展电动车违停整治排查行动，确保电动车停放有序；，联合物业对院落排水管道及相关设施进行全面排查，确保排水顺利。\n三、所获荣誉称号\n    1.2016.12，荣获“陕西省综合减灾示范社区”\n    2.2016.12，荣获“全国综合减灾示范社区”"
