        "summary": "西电设社区是西安市新城区胡家庙街道的一个典型老龄化社区，60岁以上老年居民占比60%以上。\n社区积极构建“嵌入式”养老服务体系，为老年人提供日间照料、康复理疗、助餐等多项服务。同时，社区大力推动“适老化”改造，并对60余户家庭进行了个性化适老化改造。社区创新服务模式，“红色物连网”网格示范站，推出包括上门助浴、陪诊助购在内的16项便民服务，实现对老年人的精准关怀。社区还组建了多支老年文体团队，定期举办联欢会、集体生日会等各类活动，极大地丰富了老年人的精神文化生活。\n西电设社区于2023年正式被评选为“全国示范性老年友好型社区”。"
