        "summary": "电视塔社区成立于2001年，辖5个居民小区，常住人口2850户，代管集体户9006人，流动人口较多，聚居维吾尔族、回族等15个少数民族共206人。\n社区坚持以党建为引领、服务为核心、群众满意为标准，打造“五+平台、同心驿站”服务品牌，扎实推进服务型党组织建设。先后获评“先进党支部”“西安市‘五化’标杆社区党组织”“先进基层党组织”等称号。\n近年来，社区聚焦办好惠民实事，累计为少数民族群众办理城镇居民医保200余人、落实保障性住房16户、协助外来子女入托入学28名、调解矛盾纠纷13起、举办语言等公益培训19场，有效促进了民族团结与社区和谐。先后荣获“全国民族团结进步模范集体”“省级和谐社区建设示范社区”“社区建设先进集体”等荣誉称号。"
