        "summary": "红专南路社区成立于2001年8月，辖区面积40万平方米，由3家驻地单位、4个家属区组成，常住居民4713户13565人。社区党委下设11个党支部，直管党员926名。先后荣获全国先进基层党组织、全国和谐社区建设示范社区等12次国家级荣誉，涌现出多名全国先进典型。习近平、赵乐际、刘云山等10余名党和国家领导人先后到社区考察工作并予以高度评价。\n社区充分发挥党组织领导核心作用，实行党委领导下的“五位一体”工作机制，通过“六抓”举措构建基层治理新格局，创新“区域化党建、网格化管理、组团式服务”治理品牌。深化共驻共建，打造核心价值观主题广场，建成党群服务中心、党员驿站等阵地，推动“九家”建设落地。同时，以“国际化、智慧化”为方向加强对外交流，先后接待了90多个国家高级考察团和驻华大使来社区考察。"
