        "summary": "庆华社区辖4个小区10个街坊，居民户数5631户，常住人口达1.6万余人。近年来，社区持续加强矛盾纠纷排查化解和防灾减灾等工作，先后荣获全国模范人民调解委员会、全国综合减灾示范社区等荣誉称号。\n社区成立8个调解工作组及“党芳玲调解工作室”，组建50名调解员、10名法律明白人等组成的专业调解队伍，近三年来累计化解矛盾纠纷102件，整理调解卷宗28份，通过多元化解、定期回访有效提升矛盾纠纷排查化解成效。深化“五社联动”，共享企业安全、消防设备及庆华职工医院、庆华文体中心等资源，成立4个防汛小组，建设8个应急避难场所，配备摄像头156个，定期开展应急疏散演练及“人人应急大讲堂”安全知识宣讲，人防、物防、技防综合施策，提升社区应急减灾能力水平。"
