        "summary": "十里铺街道高一社区位于县城城东4.5公里处，区域面积17.81平方公里，辖10个居民小组956户3381人，有党员77名。近年来，高一社区坚持以习近平法治思想为指导，突出党建引领、法治保障、自治强基、德治教化、智治支撑五大举措，全面提升社区治理水平。\n高一社区以“说、理、商、办、查、评”六步工作法为抓手，创新推行社区居民说事制度，建立“居民说事厅”，畅通群众诉求渠道。常态化落实“逢四研事，遇事解事”工作制度，做实人民调解工作，积极推行“人盯人”+基层社会治理机制建设，将10个居民小组、18栋移民小区楼栋分别划分为55个片区和45个治理单元，今年以来共摸排、调处矛盾纠纷16件。\n高一社区先后获得“市级平安社区”“全国民主法治示范社区”等荣誉称号。"
