        "summary": "秦岭社区成立于2007年9月，管辖服务10个小区，常住居民3570户7500余人。社区重视老年人工作，一是设立图书阅览室、棋牌室等多个活动场所，并组建了老年人志愿者协会、秦腔协会等，并多次邀请老年人参与社区组织的志愿者活动，满足老人们各方面精神文化需求。二是定期举办健康讲座、专家义诊等活动。对失能的老人、高龄老人免费理发、打扫卫生等，让他们感受到来自社区的温暖与关爱。三是连续举办九届 “好媳妇”、“好婆婆”、“最美家庭”、“文明楼栋”表彰活动，在社区营造出了浓厚的孝老、敬老氛围。今年以来累计服务老人1750人次，开展入户走访、慰问、心理辅导等130余人次。\n近年来秦岭社区被评为“全国老年友好型示范社区”“全国文明单位”“全国最美志愿服务社区”。"
