        "summary": "若羌县铁干里克镇古力巴格社区行政面积2.37平方公里，现有常住居民224户683人，设党总支1个、党支部2个，配备干部23人。\n近年来，古力巴格社区严格落实全县法治建设统一部署，紧扣“自治、法治、德治”融合发展目标，以党组织为核心组建由社区干部、法律顾问、“法律明白人”组成的法治工作队伍，挂牌设立公共法律服务工作室、人民调解室，常态化落实“一村（社区）一法律顾问”制度，提供点对点专业法律服务。依托全县“矛盾纠纷多元化解”工作机制，累计化解各类矛盾纠纷68件，妥善处置信访事项15件，解决群众急难愁盼问题50余件，将矛盾纠纷化解在早、化解在小。联合县司法局推进“智能+便民”法律服务，配备公共法律服务自助机，拓宽便民法治服务渠道。打造法治长廊等宣传阵地，通过以案释法、专题宣讲等开展普法活动20余场次，覆盖群众3410余人次。规范完善居民公约，将铸牢中华民族共同体意识、移风易俗、邻里互助等内容纳入其中，推动公约法治化规范化。\n获得荣誉：\n2017年11月获得“全国文明村镇”荣誉\n2019年6月获得“自治州先进基层党组织”荣誉\n2022年12月获得“全国民主法治示范村（社区）”荣誉\n2023年3月获得“自治州民族团结进步示范社区”荣誉"
