        "summary": "阿图什市幸福街道吾斯塘路社区成立于2002年1月，地处城区西南，辖区面积0.6平方公里，总户数1718户5210人，现有党员62名，是多民族互嵌式社区。社区以州委基层治理“八力”为抓手，打造共享“无私”塘、汇聚“一家”情党建服务品牌，推行“月七周三”服务措施，有序开展各类为民服务活动，依托幸福街道“五个五”、净城活动“四个一”等机制，开展每日志愿，每月评比及干部“每日五思”活动，构建起互嵌融合的共建共治共享治理新格局。\n获得荣誉：\n2021年12月被评为自治区“民族团结一家亲”先进集体\n2022年3月被评为2021年度全国学雷锋志愿服务100个最美志愿服务社区\n2022年7月被评为自治区民族团结进步示范社区\n2022年10月被评为自治区“扫黄打非”进基层示范点\n2023年1月被评为全国民族团结进步示范社区\n2023年6月被评为全国示范性老年友好型社区\n2024年8月定为自治区第三批城市一刻钟便民服务生活圈试点社区"
