        "summary": "西高社区成立于2010年，原为西高庄村，隶属河北省保定市莲池区杨庄乡，现有居民710户、2100人。多年来西高社区始终传承“全国先进基层党组织”“全国文明村”“全国乡村治理示范村”西高庄优良传统，坚持党建引领、文化育民的基层治理路径，自治、德治、法治一体化推进，全面打造共建共治共享的社区治理格局，同时结合社区文联持续筑牢基层思想文化阵地，用中华民族优秀传统文化和社会主义先进文化凝聚人心、汇聚力量、推动发展，全方位、多维度教育引导居民弘扬践行社会主义核心价值观，带动全民参与文艺志愿服务，走出了一条“小村庄、大文艺、高品质、新颜值”的文艺引领社区发展的大美道路。\n先后荣获“全国文明单位”“全国最美文艺志愿服务社区”“全国示范性老年友好型社区”等国家级荣誉。"
