        "summary": "杨树社区东起问津街，西至红旗大街，南起新华路，北至和平路，面积为0.6平方公里，常住居民1486户，常住人口5833人。建有党员教育室、未成年活动中心、退役军人之家、寸草心之家等13个功能室。社区构建了以“党建+”为核心的治理模式，通过网格化管理与“五社联动”机制，探索推出了党建+“6241”工程、党建+五社联动机制、党建+红墙文化、党建＋红色引领工程、党建＋网格精细化治理等居民自治创新举措。突出打造了居民议事园、楼栋夜话、吾老汇、社区心课堂、老帮老红杨互助等特色品牌，努力构建“一核多元、携手惠民、合作共治”的基层服务和治理体系，探索推动社区治理、社会自我调节、居民自治之间良性互动的社区发展模式。\n获得荣誉\n2012年获全国科普示范社区，2015年、2018年获全国民主法治示范社区，2016年、2019年获河北省志愿服务示范社区，2017年、2020年获河北省文明社区，2022年获全国示范性老年友好型社区等多项荣誉，成为基层治理的先进典范。"
