        "summary": "石河子市新城街道七社区成立于2001年，辖区总面积1.2平方公里，现有常住人口5813户、10920人，居民楼101栋，是集老旧小区改造典范与现代化治理样板于一体的综合性城市社区。\n近年来，七社区以建设“适老宜少、宜居宜业、和谐共享”社区为目标，统筹推进党建引领、多元共治与精细化服务，着力塑造覆盖全面、功能健全、机制新颖的基层治理新面貌。七社区坚持党建引领基层治理，不断深化多元共治模式，积极推行“红色卫士”志愿服务队、“三色服务法”“四亮行动”等特色机制，在养老服务、网格治理、文明创建等工作中取得了令人瞩目的成效。\n社区先后荣获“全国先进基层群众性自治组织”“全国综合减灾示范社区”“兵团优秀平安连队（社区）”“兵团文明社区”等荣誉称号。"
