        "summary": "西关街道馨园路社区（原福馨园社区）于2011年6月正式成立。其辖区东起绵山北街，西至汾秀南街，南起金融路，北达北坛西路，总面积为0.5252平方公里,划分为五个小区，16个网格，共有86栋住宅楼，4524户住户，常住人口12092人。社区支部党员21人、居民党员总数为1587人、国企退休党员342人；辖区内有282家商铺、1家怡安居物业公司及1所幼儿园。\n社区居民主要为汾西矿业职工及家属，呈现出“四多一高”的显著特征，即小区楼栋数量多、常住人口规模大、人员流动较为频繁、居民需求呈现多元化，居民文化素养整体较高，是一个居住环境适宜、人文气息浓厚的宜居型社区。为进一步提升社区老年服务的质量与水平，充分满足老年人日益增长的生活需求，西关街道馨园路社区积极采取多项有力举措，全力打造规范化、专业化的老年服务社区模式,于2021年10月荣获国家卫生健康委、全国老龄办授予的“全国示范性老年友好型社区”荣誉称号。"
