        "summary": "城区西街街道秀水苑社区成立于2009年，地处凤台西街以北、红星西街以南、西环路以东、五龙B区以西，辖区面积0.31平方公里，是集居住、教育为一体的现代化城市社区。社区现有居民2796户8095人，居民楼40栋，商铺178个，驻地单位11家，配套九年制学校、幼儿园各1所。近年来，社区以党建为引领，以共建为依托、以文化为抓手、以幸福为目标、以文明为滋养，强化阵地建设，激发文化活力，构建党群协同共治格局，赋能社区治理提质增效，先后斩获“全国文明单位”、“山西省文明社区”、山西省第一批“五星级一刻钟便民生活圈”、“2025年度晋城市文化大院”等多项荣誉，是名副其实的宜居、幸福、文明社区。"
