        "summary": "介休市西南街道光明路社区东起文明南街，西至金融路，南至新建西路，北至光明西路，辖区面积0.48平方公里，是典型的老龄化社区。现有居民3200余人，其中60岁以上老年人占比超过40%。社区聚焦老年人“医食住行乐”需求，围绕“政务服务、文体服务、健康服务、生活服务、平安服务”打造“五个十分钟便民服务圈”，全方位满足居民多元化生活需要。在此框架下，社区组建了光明路社区老年艺术团，下设舞蹈队、合唱队、二胡队等12支文艺团队，依托“我们的节日”等载体开展系列活动，实现老年人老有所为、老有所乐。同时整合社会资源，定期组织义诊、家电维修、上门理发、老年探访、送货上门等志愿服务。光明路社区凭借扎实系统的服务与创新实践，积极构建老年友好型社区，形成了服务完善、邻里和谐、文化活跃的良好局面，并于2018年被全国宣传推选学雷锋志愿服务“四个100”先进典型活动组委会授予“最美志愿服务社区”称号，于2022年被国家卫生健康委员会、全国老龄工作委员会授予“全国示范性老年友好型社区”称号，已成为区域老年友好建设的标杆范例。"
