        "summary": "榆次区西南街道南窑社区成立于2002年10月，地处榆次老城区中心，辖区东起南同蒲铁路线、西至汇通路、南起西顺城街、北至北窑街，是典型城中村。 社区现有居民2783户5637人，其中少数民族74户189人，包括回族62户171人（含流动人口4户22人）、满族11户17人、侗族1户1人。作为晋中市民族交往交流交融基地、榆次区民族团结进步工作先进社区，南窑社区以建设“社区大家庭”“民族团结之家”为目标，通过搭建平台、组织活动、贴心服务，促成了社区和谐、民族团结、互助共融的良好局面。社区先后于2018年12月获评“全国民族团结进步创建示范社区”，2019年9月被授予“全国民族团结进步模范集体”称号。"
