        "summary": "值夏社区位于江西省吉安市青原区值夏镇圩镇中心，成立于1958年，为全区历史最悠久的居委会。现有常住居民1766户4000多人，流动人口达3000多人。辖区东西临富水河，北至潇昌河，面积约1.5平方公里，青东公路贯穿全境。该镇毗邻泰和县、吉安县和吉水县，水陆通达，为周边县乡物资集散地，历来经贸发达，居民多以经商为主，辖区内设政府机关、卫生院、中小学、银行等25家单位，宾馆、景点和商超市场多达200多家。\n2022年荣获“全国民主法治示范社区”“全国综合减灾示范社区”等荣誉称号；2023年被评为“江西省四星级幸福社区”。2023年，社区的“白保忠调解室”荣获“全国模范人民调解委员会”称号。\n社区现有3000平方米的养老便民服务中心，内含娱乐室、舞蹈室、心理咨询室、儿童之家等多种功能室，常年为周边群众提供服务，打造了具有本地特色的“白保忠调解室”和“芗城义警”两大服务品牌。"
