        "summary": "古交市桃园街道桃园路社区成立于2001年，地处古交市市中心，东至大川河，西抵牛角上，南达金牛西大街，北临汾河公园，是一个多元聚集的老式居住型社区。社区划分为5个网格，10个小区，现有居民2464户6228人，户籍人口4462人。桃园路社区辖区居民楼建设年代早，呈现“老人多、商户多、单位多”的鲜明特点。桃园路社区坚持党建引领基层治理，以组织联建、资源共享、活动联办、服务联做为抓手，深化与辖区单位、企业的共建共享共创。聚焦“一老一小”重点群体需求，推动多元主体融入治理格局，有效破解老旧社区治理难题。形成了党建引领作用显著、资源整合高效、服务精准暖心、治理多元协同的和谐幸福社区，并于2021年被国家卫生健康委及全国老龄办授予“全国示范性老年友好型社区”，于2023年12月被中共山西省委宣传思想文化工作领导小组授予“山西省文明社区”，于2023年被太原市精神文明建设指导委员会授予“2020-2022文明社区”荣誉称号。"
