        "summary": "达布希勒特社区成立于2009年，地处锡林浩特市新区北部，辖区面积1.5平方公里，下辖7个居民小区，共3332户7345人，其中转移进城牧民418户672人。社区现有工作人员26名、网格员18名，中共党员95人。\n社区立足老年人与转移进城农牧民居多的特点，依托新时代文明实践站，联合包联单位打造“城市那达慕”“知书达礼·乐龄巴士”等品牌活动，建设棋牌室、那达慕体验室等功能空间，支持组建6支文化队伍，开展毡绣作品展等惠民活动，促进各族群众交往交流，提升居民获得感。社区于2019年荣获“全国民族团结进步模范集体”称号。"
