        "summary": "千山水泥社区成立于2003年6月，依托原国有小屯水泥厂（现千山水泥公司）形成。社区现有常住人口3512人、户籍人口4226人，其中党员251人、困难人群112人。自成立以来，社区始终锚定党建引领基层治理核心方向，创新构建“党支部+网格”治理架构，推行“双格融合、双员共管”工作机制，实现社企信息互通、资源共享，将党的政治优势、组织优势转化为基层治理效能，走出了一条社区共建共享共治的特色路径。社区建立企业专属网格与社区基础网格“双格融合、双员共管”机制，主动接手补助、遗属费发放等工作，及时与企业互通信息，源头化解纠纷。通过“社企联动”工作法，将企业改制引发的600余件历史遗留问题全部就地化解。2023年11月，千山水泥社区“社企联动”工作法被中央政法委评为全国新时代“枫桥经验”先进典型。"
