        "summary": "文安路社区隶属于辽宁省沈阳市和平区南湖街道，常住居民4948户、8448人，下辖住宅小区19个。社区先后获得“全国文明单位”“全国创先争优先进基层党组织”“全国和谐社区建设示范社区”“全国示范性老年友好型社区”“辽宁省先进基层党组织”“辽宁省先进社区”等国家、省、市级荣誉300余项。\n文安路社区深入贯彻落实习近平总书记提出的“社区建设光靠钱不行，要与邻为善、以邻为伴”的重要论断，以党的建设为引领，以居民需求为导向，实施“19101”服务模式，即设立1个党群服务中心、应用“9每”基层治理法、做好10项暖心服务、设立1个民生诉求反馈回音墙，将全过程人民民主贯穿老旧小区治理始终，有效调动居民群众共建美好家园、共治民生难题、共享治理成果。"
