        "summary": "永环社区共有4个居民小区，41栋居民楼，居民总户数3453户。住宅楼多建于上世纪90年代，属于典型的老旧小区，社区内老年群体居多，应急能力较弱，因此社区十分重视防灾减灾工作。社区会定期组织居民进行消防安全讲座、消防应急演练，以保证居民掌握自救和互救的方法；同时针对重点人群建立了台账，明确包保责任人，定期入户精准关注；联合物业定期清理楼道及安全通道杂物，确保安全通道畅通；还在两个大的小区建立了微型消防站，其他两个小区配备了消防设施，以保障居民的安全。在社区努力下也取得了一定成绩，永环社区曾于2015年10月荣获辽宁省减灾委员会颁发的“2015年度辽宁省减灾示范社区”同年12月又荣获国家减灾委员会颁发的2015年“全国综合减灾示范社区”。"
