        "summary": "响水助力微梦公益协会于2008年创办，2012年6月登记注册，是专注于志愿服务和公益事业的非营利性社会组织。协会现有专职工作人员7人、兼职人员21人，其中正式党员7人、预备党员1人、入党积极分子1人，拥有江苏省红十字应急救援师资2人、中级养老护理员6人、注册志愿者3500余人（党员志愿者占比约65%）。目前，运营16个品牌公益项目。\n协会探索实施“党建+公益”的典型做法，积极投身基层治理，在扶贫助困、志愿服务等方面做出较大的成就，联合多部门开展各类主题活动，弘扬社会正能量。\n荣获全国先进基层党组织、江苏省先进基层党组织、江苏省示范性社会组织、全国学雷锋志愿服务“四个100”最佳志愿服务项目、第四届全国基层党建创新优秀案例等多项国家、省、市级荣誉。"
