        "summary": "京口路社区位于江苏省镇江市京口区正东路街道，面积约0.59平方公里，现有居民3525户6690人、党员205名。\n社区始终坚持“党建让社区生活更美好”理念，创新推行“665”工作法，建强党群服务、居民生活、低碳生活、城市乡愁、日间照料、医疗卫生“6大中心”服务阵地，打造食品、道德、艺术、民生、健康、时间“6大银行”服务模式，针对不同群体精准分类、动态设星，做实5星走访服务，创新打造“5换1”制度、“336”工作法等，以“有色彩有感知的党建”引领“有成效有温度的社区治理服务”，被中组部城市基层党建调研组评价为“走在全国前列”。\n社区先后荣获“全国先进基层党组织”“全国最美志愿服务社区”“全国敬老文明号”等荣誉称号。",
